def getShippingCost(country, weightLbs, orderTotal=0):
    country = country.upper()
    if country == 'US' or country == 'USA':
        if orderTotal >= FREE_SHIPPING_LIMIT:
            return 0.0
        if weightLbs <= 1:
            return 4.95
        elif weightLbs <= 5:
            return 7.95
        elif weightLbs <= 20:
            return 14.95
        else:
            return 14.95 + (weightLbs - 20) * 0.5
    elif country == 'CA' or country == 'MX':
        if weightLbs <= 1:
            return 12.95
        elif weightLbs <= 5:
            return 21.95
        else:
            return 44.95
    elif country in ['GB', 'UK', 'DE', 'FR', 'NL', 'IE', 'ES', 'IT']:
        if weightLbs <= 1:
            return 14.95
        elif weightLbs <= 5:
            return 24.95
        else:
            return 54.95
    else:
        if weightLbs <= 1:
            return 19.95
        return 79.95
